query.data:
{{
  (() => {
    const timeframe = (typeof SelectTimeframe !== 'undefined' && SelectTimeframe.selectedOptionValue) ? SelectTimeframe.selectedOptionValue : '1M';
    const portfolio = (typeof SelectPortfolioFilter !== 'undefined' && SelectPortfolioFilter.selectedOptionValue) ? SelectPortfolioFilter.selectedOptionValue : 'ALL';
    let days = 30;
    if (timeframe === '1W') days = 7;
    if (timeframe === '1M') days = 30;
    if (timeframe === '1Y') days = 365;
    if (timeframe === 'ALL') days = 3650;

    const d = new Date();
    d.setDate(d.getDate() - days);
    return {
      portfolio: portfolio === 'ALL' ? 'ALL' : portfolio,
      date: { $gte: d.toISOString().split('T')[0] }
    };
  })()
}}

